record.field:
activity_type = env.ref(
    'fmcg_business_automation.mail_activity_type_missing_lot_serial'
)

for line in records:
    picking = line.picking_id
    if not picking:
        continue

    existing = env['mail.activity'].search_count([
        ('res_model', '=', 'stock.picking'),
        ('res_id', '=', picking.id),
        ('activity_type_id', '=', activity_type.id),
    ])

    if not existing:
        picking.activity_schedule(
            activity_type_id=activity_type.id,
            user_id=(picking.user_id or env.user).id,
            summary='Bổ sung Lot/Serial',
        )
